package com.portfoliv.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.net.http.SslError;import android.webkit.*;import android.view.*;import android.widget.*;import android.print.*;import org.json.*;import java.io.*;import java.net.URL;import java.net.HttpURLConnection;import java.util.*;
public class MainActivity extends Activity {
 static final String HOME="https://portfoliv.onrender.com/",HOST="portfoliv.onrender.com";
 WebView web; ProgressBar progress; ValueCallback<Uri[]> picker; byte[] pending;String pendingName="포트폴리브.pdf";boolean started=false;Dialog popup;
 boolean trusted(String value){try{Uri u=Uri.parse(value);return "https".equals(u.getScheme())&&HOST.equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 @Override public void onCreate(Bundle state){super.onCreate(state); LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff7f9f3);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,5));LinearLayout bar=new LinearLayout(this);Button retry=new Button(this);retry.setText("새로고침");retry.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("저장하지 않은 내용을 유지하려면 아니오를 누르세요. 다시 불러올까요?").setNegativeButton("아니오",null).setPositiveButton("예",(d,w)->web.reload()).show());Button browser=new Button(this);browser.setText("브라우저에서 열기");browser.setOnClickListener(v->external(HOME));bar.addView(retry);bar.addView(browser);root.addView(bar);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);configure(web,false);if(state==null||web.restoreState(state)==null)web.loadUrl(HOME);}
 void configure(WebView view,boolean print){WebSettings s=view.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMediaPlaybackRequiresUserGesture(true);s.setSafeBrowsingEnabled(true);s.setUserAgentString(s.getUserAgentString()+" PortfolivApp/1.0.0");CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(view,false);
 view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(!r.isForMainFrame())return false;String url=r.getUrl().toString();if(trusted(url)||print&&"about:blank".equals(url))return false;external(url);return true;}@Override public void onReceivedSslError(WebView w,SslErrorHandler h,SslError e){h.cancel();toast("보안 연결을 확인하지 못했습니다. 연결을 우회하지 않습니다.");}@Override public void onPageFinished(WebView w,String u){CookieManager.getInstance().flush();if(w==web){progress.setVisibility(View.GONE);if(trusted(u))web.evaluateJavascript("(()=>{const n=document.getElementById('portfoliv-native-print');if(n)n.remove();})()",null);}else if(print){w.evaluateJavascript("window.print=()=>{document.title='portfoliv-print-request'}",null);}}@Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())toast("연결을 확인해주세요. 메뉴에서 다시 불러올 수 있습니다.");}});
 view.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView w,int value){if(w==web){progress.setProgress(value);progress.setVisibility(value==100?View.GONE:View.VISIBLE);}}@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams params){if(picker!=null)picker.onReceiveValue(null);picker=cb;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(intent,10);}catch(Exception e){picker.onReceiveValue(null);picker=null;toast("파일 선택 앱을 사용할 수 없습니다.");}return true;}@Override public boolean onJsConfirm(WebView w,String u,String m,JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(m).setNegativeButton("아니오",(d,x)->r.cancel()).setPositiveButton("예",(d,x)->r.confirm()).setOnCancelListener(d->r.cancel()).show();return true;}@Override public boolean onCreateWindow(WebView w,boolean dialog,boolean gesture,Message msg){if(!gesture||!trusted(web.getUrl()))return false;if(popup!=null)popup.dismiss();WebView child=new WebView(MainActivity.this);configure(child,true);popup=new Dialog(MainActivity.this);LinearLayout container=new LinearLayout(MainActivity.this);container.setOrientation(1);LinearLayout actions=new LinearLayout(MainActivity.this);Button save=new Button(MainActivity.this);save.setText("PDF 저장 · 인쇄");save.setOnClickListener(v->((PrintManager)getSystemService(PRINT_SERVICE)).print("포트폴리브",child.createPrintDocumentAdapter("포트폴리브"),new PrintAttributes.Builder().build()));Button close=new Button(MainActivity.this);close.setText("닫기");close.setOnClickListener(v->popup.dismiss());actions.addView(save);actions.addView(close);container.addView(actions);container.addView(child,new LinearLayout.LayoutParams(-1,0,1));popup.setContentView(container);popup.setOnDismissListener(d->{child.destroy();popup=null;});popup.show();popup.getWindow().setLayout(-1,-1);((WebView.WebViewTransport)msg.obj).setWebView(child);msg.sendToTarget();return true;}@Override public void onCloseWindow(WebView w){if(popup!=null)popup.dismiss();}});
 view.setDownloadListener((url,ua,disposition,type,length)->{if(view!=web||!trusted(web.getUrl())){toast("본인 화면에서 파일을 내려받아주세요.");return;}if(url.startsWith("blob:"+HOME.substring(0,HOME.length()-1)+"/")){String js="(async()=>{const r=await fetch("+JSONObject.quote(url)+");const b=await r.blob();if(b.size>52428800)return JSON.stringify({error:'size'});return await new Promise(resolve=>{const f=new FileReader();f.onload=()=>resolve(JSON.stringify({data:f.result,name:(document.querySelector('a[href='+JSON.stringify("+JSONObject.quote(url)+")+']')||{}).download||'포트폴리브.pdf'}));f.readAsDataURL(b);});})()"; // evaluateJavascript cannot await promises; use a polled main-frame result, never a JavaScript interface.
 web.evaluateJavascript("window.__portfolivDownload=null;"+js+".then(v=>window.__portfolivDownload=v).catch(()=>window.__portfolivDownload='error')",null);pollDownload(0);}
 else if(trusted(url)){web.evaluateJavascript("sessionStorage.getItem('portfolioTabToken')",token->{String tab="";try{tab=new JSONArray("["+token+"]").optString(0,"");}catch(Exception e){}download(url,CookieManager.getInstance().getCookie(HOME),tab);});}else external(url);});}
 void pollDownload(int attempt){if(attempt>120){toast("파일 준비 시간이 초과했습니다.");return;}new Handler(Looper.getMainLooper()).postDelayed(()->{if(!trusted(web.getUrl()))return;web.evaluateJavascript("window.__portfolivDownload",raw->{try{Object value=new JSONArray("["+raw+"]").get(0);if(value==JSONObject.NULL){pollDownload(attempt+1);return;}JSONObject result=new JSONObject((String)value);String data=result.getString("data");prepare(android.util.Base64.decode(data.substring(data.indexOf(',')+1),0),result.optString("name","포트폴리브.pdf"));web.evaluateJavascript("delete window.__portfolivDownload",null);}catch(Exception e){toast("파일을 준비하지 못했습니다.");}});},250);}
 void download(String address,String cookie,String tab){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(30000);c.setReadTimeout(30000);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(!tab.isEmpty())c.setRequestProperty("X-Portfolio-Tab",tab);if(c.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>52428800)throw new IOException();out.write(buf,0,n);}}String type=c.getContentType();c.disconnect();byte[] bytes=out.toByteArray();runOnUiThread(()->prepare(bytes,type!=null&&type.contains("pdf")?"포트폴리브.pdf":"포트폴리브-첨부파일"));}catch(Exception e){runOnUiThread(()->toast("다운로드를 완료하지 못했습니다. 로그인 상태를 확인해주세요."));}}).start();}
 void prepare(byte[] bytes,String name){if(pending!=null){toast("이전 파일 저장을 먼저 마쳐주세요.");return;}pending=bytes;pendingName=name.replaceAll("[\\\\/\\p{Cntrl}]","_");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(name.endsWith(".pdf")?"application/pdf":"application/octet-stream");intent.putExtra(Intent.EXTRA_TITLE,pendingName);try{startActivityForResult(intent,11);}catch(Exception e){pending=null;toast("파일 저장 앱을 사용할 수 없습니다.");}}
 void external(String value){Uri uri=Uri.parse(value);String scheme=uri.getScheme();if(!Arrays.asList("https","mailto","tel").contains(scheme))return;try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){toast("링크를 열 앱이 없습니다.");}}
 void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&picker!=null){Uri[] selected=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){selected=new Uri[data.getClipData().getItemCount()];for(int i=0;i<selected.length;i++)selected[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)selected=new Uri[]{data.getData()};}picker.onReceiveValue(selected);picker=null;}if(request==11){byte[] bytes=pending;pending=null;if(result==RESULT_OK&&data!=null&&bytes!=null)try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(bytes);toast("파일을 저장했습니다.");}catch(Exception e){toast("파일을 저장하지 못했습니다.");}}}
 @Override protected void onResume(){super.onResume();web.onResume();if(started&&trusted(web.getUrl()))web.evaluateJavascript("window.portfolioAuth&&window.portfolioAuth.refresh()",null);started=true;}
 @Override protected void onPause(){web.onPause();CookieManager.getInstance().flush();super.onPause();}
 @Override public void onBackPressed(){if(popup!=null){popup.dismiss();return;}if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override public boolean onCreateOptionsMenu(Menu menu){menu.add("다시 불러오기");menu.add("브라우저에서 열기");return true;}
 @Override public boolean onOptionsItemSelected(MenuItem item){if(item.getTitle().equals("다시 불러오기"))new AlertDialog.Builder(this).setMessage("저장하지 않은 작성 내용이 사라질 수 있습니다. 다시 불러올까요?").setNegativeButton("아니오",null).setPositiveButton("예",(d,w)->web.reload()).show();else external(HOME);return true;}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(picker!=null)picker.onReceiveValue(null);if(popup!=null)popup.dismiss();pending=null;web.destroy();super.onDestroy();}
}
